package checker

import "github.com/microsoft/typescript-go/internal/ast"

type StringMappingOwnerControl struct {
	DistinctOwners, DistinctGenericTypes, RepeatTypes, SharedLiteral, PreservedOwners bool
	CrossOwnerRelationRefused, SameOwnerInference, CrossOwnerInferenceRefused         bool
	Values                                                                            []string
}

func (c *Checker) QualifyStringMappingOwners(file *ast.SourceFile, reverse bool) StringMappingOwnerControl {
	raw := c.getGlobalTypeAliasSymbol("Uppercase", 1, false)
	if raw == nil {
		panic("Uppercase")
	}
	head := c.cloneSymbol(raw)
	twin := c.cloneSymbol(raw)
	lower := c.cloneSymbol(c.getGlobalTypeAliasSymbol("Lowercase", 1, false))
	parameter := c.getLocalTypeParametersOfClassOrInterfaceOrTypeAlias(c.getSymbolOfDeclaration(file.Statements.Nodes[0]))[0]
	literal := c.getStringLiteralType("Mixed")
	order := []*ast.Symbol{raw, head, twin}
	if reverse {
		order = []*ast.Symbol{twin, head, raw}
	}
	row := StringMappingOwnerControl{DistinctOwners: raw != head && raw != twin && head != twin, DistinctGenericTypes: true, RepeatTypes: true, SharedLiteral: true, PreservedOwners: true, CrossOwnerRelationRefused: true, SameOwnerInference: true, CrossOwnerInferenceRefused: true}
	var images []*Type
	var first *Type
	for _, owner := range order {
		image := c.getStringMappingType(owner, parameter)
		row.PreservedOwners = row.PreservedOwners && image.symbol == owner
		row.RepeatTypes = row.RepeatTypes && c.getStringMappingType(owner, parameter) == image && c.getStringMappingType(owner, image) == image
		stringImage := c.getStringMappingType(owner, c.stringType)
		row.DistinctGenericTypes = row.DistinctGenericTypes && image != stringImage
		inferences := []*InferenceInfo{newInferenceInfo(parameter)}
		c.inferTypes(inferences, stringImage, image, InferencePriorityNone, false)
		row.SameOwnerInference = row.SameOwnerInference && len(inferences[0].candidates) == 1 && inferences[0].candidates[0] == c.stringType
		for _, previous := range images {
			refused := []*InferenceInfo{newInferenceInfo(parameter)}
			c.inferTypes(refused, stringImage, previous, InferencePriorityNone, false)
			row.CrossOwnerInferenceRefused = row.CrossOwnerInferenceRefused && len(refused[0].candidates) == 0 && len(refused[0].contraCandidates) == 0
			row.DistinctGenericTypes = row.DistinctGenericTypes && previous != image
			row.CrossOwnerRelationRefused = row.CrossOwnerRelationRefused && !c.isTypeAssignableTo(previous, image)
		}
		concrete := c.instantiateType(image, newSimpleTypeMapper(parameter, literal))
		row.Values = append(row.Values, getStringLiteralValue(concrete))
		if first == nil {
			first = concrete
		} else {
			row.SharedLiteral = row.SharedLiteral && first == concrete
		}
		row.RepeatTypes = row.RepeatTypes && c.instantiateType(image, newSimpleTypeMapper(parameter, c.stringType)) == stringImage
		if !c.isMemberOfStringMapping(concrete, stringImage) || c.isMemberOfStringMapping(literal, stringImage) {
			panic("mapping membership")
		}
		nested := c.getStringMappingType(lower, image)
		row.Values = append(row.Values, getStringLiteralValue(c.instantiateType(nested, newSimpleTypeMapper(parameter, literal))))
		images = append(images, image)
	}
	return row
}

